/*
  ND DMX NODE 4U v2.2 - W5500-EVB-Pico2 / RP2350
  W5500-EVB-Pico2 / RP2350 + integrated W5500 + four MAX485 DMX TX
  outputs and ESP32-C5 UART

  Recommended Arduino-Pico settings:
    Board:       W5500-EVB-Pico2 / RP2350 (or the matching RP2350 board entry)
    CPU Speed:   Board/core default
    Flash Size:  Board default (integrated 16 Mbit flash)
    USB Stack:   Pico SDK
    Optimize:    Small (-Os)
*/

