// Exact runtime-equivalence branch copied from the hardware-validated
// /private/tmp/W5500_ONLY_TEST/W5500_ONLY_TEST.ino.  Keep this branch free of
// production globals, watchdog, EEPROM, PIO, multicore, sockets and services.
#define W5500_MISO_PIN 16
#define W5500_CS_PIN   17
#define W5500_SCK_PIN  18
#define W5500_MOSI_PIN 19
#define W5500_RST_PIN  20
#define W5500_INT_PIN  21
#define HARDWARE_LED_PIN 25

ArduinoWiznet5500lwIP Ethernet(W5500_CS_PIN, SPI, W5500_INT_PIN);
byte mac[] = { 0x02, 0x4E, 0x44, 0x34, 0x55, 0x01 };

static uint32_t lastLinkPollMs = 0;
static uint32_t lastLedToggleMs = 0;
static bool ledState = false;

static void serviceLinkLed() {
  const uint32_t now = millis();
  if (now - lastLinkPollMs < 1000u) return;
  lastLinkPollMs = now;

  const bool linkUp = Ethernet.linkStatus() == LinkON;
  if (linkUp) {
    ledState = true;
    digitalWrite(HARDWARE_LED_PIN, HIGH);
  } else if (now - lastLedToggleMs >= 1000u) {
    ledState = !ledState;
    digitalWrite(HARDWARE_LED_PIN, ledState ? HIGH : LOW);
    lastLedToggleMs = now;
  }
  Serial.print(F("[W5500 TEST] link="));
  Serial.println(linkUp ? F("UP") : F("DOWN"));
}

void setup() {
  Serial.begin(115200);
  delay(1000);
  pinMode(HARDWARE_LED_PIN, OUTPUT);
  digitalWrite(HARDWARE_LED_PIN, LOW);

  Serial.println(F("W5500_ONLY_TEST RP2350 / W5500-EVB-Pico2"));
  Serial.println(F("[TEST] Integrated W5500 initialization begins"));

  pinMode(W5500_RST_PIN, OUTPUT);
  digitalWrite(W5500_RST_PIN, LOW);
  delay(100);
  digitalWrite(W5500_RST_PIN, HIGH);
  delay(500);

  SPI.setRX(W5500_MISO_PIN);
  SPI.setCS(W5500_CS_PIN);
  SPI.setSCK(W5500_SCK_PIN);
  SPI.setTX(W5500_MOSI_PIN);
  SPI.begin();

  IPAddress staticIP(10, 10, 10, 10);
  IPAddress dnsServer(10, 10, 10, 1);
  IPAddress gateway(10, 10, 10, 1);
  IPAddress subnetMask(255, 255, 255, 0);
  const bool ethernetStarted = Ethernet.begin(mac, staticIP, dnsServer, gateway, subnetMask);

  const bool hardwareOk = Ethernet.hardwareStatus() != EthernetNoHardware;
  const bool ipOk = Ethernet.localIP() == staticIP;
  const bool linkUp = Ethernet.linkStatus() == LinkON;
  Serial.print(F("[TEST] W5500 init: "));
  Serial.println(ethernetStarted && hardwareOk ? F("PASS") : F("FAIL"));
  Serial.print(F("[TEST] IP: ")); Serial.println(ipOk ? F("PASS 10.10.10.10") : F("FAIL"));
  Serial.print(F("[TEST] Link: ")); Serial.println(linkUp ? F("UP") : F("DOWN"));
  Serial.println(F("[TEST] Ethernet initialized once; no loop reinitialization"));

  ledState = linkUp;
  digitalWrite(HARDWARE_LED_PIN, linkUp ? HIGH : LOW);
  lastLedToggleMs = millis();
}

void loop() {
  serviceLinkLed();
}

