// Arduino's automatic prototype generator can place calcCRC() before the
// full Config definition. Forward-declare the type for the .ino build.
struct Config;

static const uint32_t RESET_DIAG_MAGIC = 0x4E444D00u;
static uint32_t previousResetCode = 0;
static uint8_t previousBootStage = 0;
static bool previousBootCompleted = true;
enum RuntimeStage : uint8_t { RT_LOOP_START, RT_NETWORK_RX, RT_ARTNET, RT_SACN, RT_WEB, RT_DMX, RT_LOOP_COMPLETE };
static volatile RuntimeStage runtimeStage = RT_LOOP_START;
enum BootStage : uint8_t { BOOT_START = 0, CONFIG_LOAD, DMX_INIT, W5500_RESET, SPI_INIT, ETHERNET_INIT, ETHERNET_READY, SACN_INIT, WEB_SERVER_INIT, ARTNET_INIT, CORE_SYNC, BOOT_COMPLETE };
static BootStage currentBootStage = BOOT_START;
extern volatile uint32_t core1_heartbeat;
extern volatile uint32_t lCount1;

static const char* resetReason(uint32_t code) {
  switch (code) {
    case 1: return "Core 1 heartbeat stalled";
    case 2: return "Watchdog expired";
    case 3: return "PIO recovery failure";
    default: return code ? "Unknown reset" : "Power-on/software reset";
  }
}
static const char* bootStageName(uint8_t stage) {
  switch (stage) {
    case BOOT_START: return "BOOT_START"; case CONFIG_LOAD: return "CONFIG_LOAD";
    case DMX_INIT: return "DMX_INIT"; case W5500_RESET: return "W5500_RESET"; case SPI_INIT: return "SPI_INIT";
    case ETHERNET_INIT: return "ETHERNET_INIT"; case ETHERNET_READY: return "ETHERNET_READY"; case SACN_INIT: return "SACN_INIT";
    case WEB_SERVER_INIT: return "WEB_SERVER_INIT"; case ARTNET_INIT: return "ARTNET_INIT"; case CORE_SYNC: return "CORE_SYNC";
    case BOOT_COMPLETE: return "BOOT_COMPLETE"; default: return "UNKNOWN_STAGE";
  }
}
// scratch[0]=magic; scratch[1]=reset code(0..7), stage(8..15), complete(16), attempts(24..31)
// scratch[2]=Core 1 heartbeat; scratch[3]=Core 1 loop counter; scratch[4]=runtime stage.
static void recordBootStage(BootStage stage) {
  currentBootStage = stage;
  const uint32_t attempts = ((watchdog_hw->scratch[1] >> 24) + 1u) & 0xFFu;
  watchdog_hw->scratch[0] = RESET_DIAG_MAGIC;
  watchdog_hw->scratch[1] = (static_cast<uint32_t>(previousResetCode) & 0xFFu) | (static_cast<uint32_t>(stage) << 8) | (attempts << 24);
  Serial.print(F("[BOOT ")); Serial.print(static_cast<int>(stage)); Serial.print(F("] ")); Serial.println(bootStageName(stage));
  watchdog_update();
}
static void markBootComplete() {
  currentBootStage = BOOT_COMPLETE;
  watchdog_hw->scratch[1] = (watchdog_hw->scratch[1] & 0xFF00FFFFu) | (static_cast<uint32_t>(BOOT_COMPLETE) << 8) | (1u << 16);
  Serial.println(F("[BOOT OK] COMPLETE"));
}

static void saveResetDiagnostic(uint32_t code) {
  watchdog_hw->scratch[0] = RESET_DIAG_MAGIC;
  watchdog_hw->scratch[1] = (code & 0xFFu) | (static_cast<uint32_t>(currentBootStage) << 8) |
                            (currentBootStage == BOOT_COMPLETE ? (1u << 16) : 0u);
  watchdog_hw->scratch[2] = __atomic_load_n(&core1_heartbeat, __ATOMIC_RELAXED);
  watchdog_hw->scratch[3] = __atomic_load_n(&lCount1, __ATOMIC_RELAXED);
  watchdog_hw->scratch[4] = static_cast<uint32_t>(runtimeStage);
}

static const char* runtimeStageName(uint8_t stage) {
  switch (stage) { case RT_LOOP_START: return "LOOP_START"; case RT_NETWORK_RX: return "NETWORK_RX"; case RT_ARTNET: return "ARTNET"; case RT_SACN: return "SACN"; case RT_WEB: return "WEB"; case RT_DMX: return "DMX"; case RT_LOOP_COMPLETE: return "LOOP_COMPLETE"; default: return "UNKNOWN"; }
}
static inline void setRuntimeStage(RuntimeStage stage) { runtimeStage = stage; watchdog_hw->scratch[4] = static_cast<uint32_t>(stage); }

