static constexpr uint32_t ESP_UART_TX_QUEUE_SIZE = 32768;
// Arduino-Pico 6.1.0 reports SerialUART::availableForWrite() as 0/1 and
// write() can wait for the UART to accept each byte. Bound each service pass
// so a proxied Wi-Fi response cannot starve native W5500 packet servicing.
static constexpr uint16_t ESP_UART_TX_SERVICE_BUDGET = 64;
static uint8_t espUartTxQueue[ESP_UART_TX_QUEUE_SIZE];
static uint32_t espUartTxHead = 0;
static uint32_t espUartTxTail = 0;
static bool espUartTxOverflowReported = false;
class UartDashboardWriter;

static const char UART_B64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static size_t b64Encode(const uint8_t* in, size_t len, char* out, size_t cap) {
  size_t oi = 0;
  for (size_t i = 0; i < len; i += 3) {
    if (oi + 4 >= cap) return 0;
    const uint32_t v = (static_cast<uint32_t>(in[i]) << 16) |
      ((i + 1 < len ? in[i + 1] : 0) << 8) | (i + 2 < len ? in[i + 2] : 0);
    out[oi++] = UART_B64[(v >> 18) & 63]; out[oi++] = UART_B64[(v >> 12) & 63];
    out[oi++] = i + 1 < len ? UART_B64[(v >> 6) & 63] : '=';
    out[oi++] = i + 2 < len ? UART_B64[v & 63] : '=';
  }
  out[oi] = '\0'; return oi;
}
static int b64Value(char c) { if (c >= 'A' && c <= 'Z') return c - 'A'; if (c >= 'a' && c <= 'z') return c - 'a' + 26; if (c >= '0' && c <= '9') return c - '0' + 52; if (c == '+') return 62; if (c == '/') return 63; return -1; }
static size_t b64Decode(const char* in, uint8_t* out, size_t cap) {
  size_t oi = 0; int val = 0; int bits = -8;
  for (const char* p = in; *p; ++p) { if (*p == '=') break; const int n = b64Value(*p); if (n < 0) return 0; val = (val << 6) | n; bits += 6; if (bits >= 0) { if (oi >= cap) return 0; out[oi++] = (val >> bits) & 255; bits -= 8; } }
  return oi;
}
static void serviceEspUartTx() {
  uint16_t sent = 0;
  while (sent < ESP_UART_TX_SERVICE_BUDGET &&
         espUartTxTail != espUartTxHead && Serial2.availableForWrite() > 0) {
    if (Serial2.write(espUartTxQueue[espUartTxTail]) == 1) ++espUartTxBytes;
    espUartTxTail = (espUartTxTail + 1u) % ESP_UART_TX_QUEUE_SIZE;
    ++sent;
  }
}
static void recordInvalidEspFrame(const char* line, const char* reason) {
  ++espUartInvalidFrames;
  lastInvalidFrameLength = static_cast<uint16_t>(strlen(line));
  strncpy(lastInvalidFrameReason, reason ? reason : "OTHER", sizeof(lastInvalidFrameReason) - 1);
  lastInvalidFrameReason[sizeof(lastInvalidFrameReason) - 1] = '\0';
  size_t n = strlen(line); if (n > sizeof(lastInvalidFrame) - 1) n = sizeof(lastInvalidFrame) - 1;
  for (size_t i = 0; i < n; ++i) {
    const unsigned char c = static_cast<unsigned char>(line[i]);
    lastInvalidFrame[i] = (c >= 32 && c <= 126) ? static_cast<char>(c) : '?';
  }
  lastInvalidFrame[n] = '\0';
}
static void copyReqPath(const uint8_t* request, size_t length) {
  lastReqPath[0] = '\0';
  const char* begin = reinterpret_cast<const char*>(request);
  const char* first = strchr(begin, ' '); if (!first) return; ++first;
  const char* end = strchr(first, ' '); if (!end) end = begin + length;
  size_t n = static_cast<size_t>(end - first); if (n >= sizeof(lastReqPath)) n = sizeof(lastReqPath) - 1;
  memcpy(lastReqPath, first, n); lastReqPath[n] = '\0';
}
static void copyHttpStatus(const uint8_t* response, size_t length) {
  lastResponseStatus[0] = '\0';
  size_t space = 0; while (space < length && response[space] != ' ') ++space;
  if (space >= length) return; ++space;
  size_t end = space; while (end < length && response[end] != ' ' && response[end] != '\r' && response[end] != '\n') ++end;
  size_t n = end - space; if (n >= sizeof(lastResponseStatus)) n = sizeof(lastResponseStatus) - 1;
  memcpy(lastResponseStatus, response + space, n); lastResponseStatus[n] = '\0';
}
static void sendEspFrame(const char* type, uint16_t id = 0, const char* payload = nullptr) {
  if (!espUartReady) return;
  char frame[360];
  const int count = snprintf(frame, sizeof(frame), payload ? "ND1|%s|%u|%s\n" : "ND1|%s|%u\n", type, id, payload ? payload : "");
  if (count <= 0 || static_cast<size_t>(count) >= sizeof(frame)) return;
  const uint32_t used = (espUartTxHead + ESP_UART_TX_QUEUE_SIZE - espUartTxTail) % ESP_UART_TX_QUEUE_SIZE;
  if (static_cast<uint32_t>(count) >= ESP_UART_TX_QUEUE_SIZE - used) {
    if (!espUartTxOverflowReported) { Serial.println(F("[WARN] ESP UART TX queue full; frame dropped")); espUartTxOverflowReported = true; }
    return;
  }
  ++espUartTxFrames;
  if (!strcmp(type, "RESP")) ++espUartRespFrames;
  else if (!strcmp(type, "DATA")) ++espUartDataFrames;
  else if (!strcmp(type, "END")) ++espUartEndFrames;
  for (int i = 0; i < count; ++i) {
    espUartTxQueue[espUartTxHead] = static_cast<uint8_t>(frame[i]);
    espUartTxHead = (espUartTxHead + 1u) % ESP_UART_TX_QUEUE_SIZE;
  }
}
static bool uartField(const char* line, uint8_t field, char* out, size_t cap) {
  const char* p = line; for (uint8_t i = 0; i < field; ++i) { p = strchr(p, '|'); if (!p) return false; ++p; }
  const char* e = strchr(p, '|'); if (!e) e = p + strlen(p); const size_t n = static_cast<size_t>(e - p);
  if (n >= cap) return false; memcpy(out, p, n); out[n] = '\0'; return true;
}
static void sendEspHttpResponse(uint16_t id, UartDashboardWriter& response);
static void handleEspFrame(const char* line);

void initEspUart() {
  Serial2.setTX(ESP_UART_TX_PIN);
  Serial2.setRX(ESP_UART_RX_PIN);
  Serial2.begin(ESP_UART_BAUD);
  espUartReady = true;
  sendEspFrame("HELLO", 0, "1");
  Serial.print(F("[DIAG] ESP32 UART: PASS (TX GP")); Serial.print(ESP_UART_TX_PIN);
  Serial.print(F(" / RX GP")); Serial.print(ESP_UART_RX_PIN);
  Serial.print(F(" / ")); Serial.print(ESP_UART_BAUD); Serial.println(F(" baud)"));
}

void serviceEspUart() {
  if (!espUartReady) return;
  serviceEspUartTx();
  while (Serial2.available() > 0) {
    const char c = static_cast<char>(Serial2.read());
    ++espUartRxBytes;
    if (c == '\n' || c == '\r') {
      if (espUartRxOverflowActive) {
        ++espUartRxLines;
        espUartRxLine[sizeof(espUartRxLine) - 1] = '\0';
        recordInvalidEspFrame(espUartRxLine, "OVERFLOW");
        espUartRxLength = 0;
        espUartRxOverflowActive = false;
      } else if (espUartRxLength > 0) {
        ++espUartRxLines;
        espUartRxLine[espUartRxLength] = '\0';
        handleEspFrame(espUartRxLine);
        espUartRxLength = 0;
      }
    } else if (espUartRxLength < sizeof(espUartRxLine) - 1) {
      espUartRxLine[espUartRxLength++] = c;
    } else {
      ++espUartRxOverflowCount;
      espUartRxOverflowActive = true;
      if (espUartRxLength < sizeof(espUartRxLine) - 1) ++espUartRxLength;
    }
  }
  const uint32_t now = millis();
  if (now - lastEspUartHeartbeatMs >= 5000u) {
    sendEspFrame("HB");
    lastEspUartHeartbeatMs = now;
  }
  serviceEspUartTx();
}

