#define ESP_UART_REQUEST_MAX 512
static uint32_t spiCrc32(const uint8_t *p, size_t n) { return ND_SPI::crc32(p, n); }
static bool spiQueueFrame(uint8_t type, uint32_t sequence, uint16_t flags, uint32_t channel, const uint8_t *payload, uint16_t length, bool lighting = false) {
  const uint8_t next = uint8_t((spiQueueHead + 1u) % ESP_SPI_QUEUE_DEPTH);
  if (next == spiQueueTail) { if (lighting) ++spiLightingDrops; else ++spiTxDrops; return false; }
  ND_SPI::build(spiQueue[spiQueueHead], type, sequence, flags, channel, payload, length); spiQueueHead = next; ++espUartTxFrames; return true;
}
static bool spiPop(uint8_t *out) { if (spiQueueTail == spiQueueHead) return false; memcpy(out, spiQueue[spiQueueTail], ND_SPI::FRAME_BYTES); spiQueueTail = uint8_t((spiQueueTail + 1u) % ESP_SPI_QUEUE_DEPTH); return true; }
static void queueSpiHello() { uint8_t p[4] = { 'R', 'P', '3', '5' }; spiQueueFrame(ND_SPI::SPI_MSG_HELLO, spiSequence, ND_SPI::FLAG_FIRST | ND_SPI::FLAG_LAST, 0, p, sizeof(p)); }
static void queueSpiStatusSubscription(const char *subscriptions = "1,2,3,4") { char s[64]; snprintf(s, sizeof(s), "SUB|%s", subscriptions ? subscriptions : "1,2,3,4"); spiQueueFrame(ND_SPI::SPI_MSG_STATUS_RESPONSE, spiSequence, ND_SPI::FLAG_FIRST | ND_SPI::FLAG_LAST, 0, reinterpret_cast<const uint8_t*>(s), uint16_t(strlen(s))); }
static void sendEspFrame(const char *type, uint16_t id = 0, const char *payload = nullptr) {
  if (!strcmp(type, "HELLO")) queueSpiHello();
  else if (!strcmp(type, "SUB")) queueSpiStatusSubscription(payload);
  else if (!strcmp(type, "HB")) { const char *s = "HB"; spiQueueFrame(ND_SPI::SPI_MSG_STATUS_RESPONSE, spiSequence, ND_SPI::FLAG_FIRST | ND_SPI::FLAG_LAST, 0, reinterpret_cast<const uint8_t*>(s), 2); }
  else if (!strcmp(type, "WIFI_SET") && payload) spiQueueFrame(ND_SPI::SPI_MSG_STATUS_REQUEST, spiSequence, ND_SPI::FLAG_FIRST | ND_SPI::FLAG_LAST, id, reinterpret_cast<const uint8_t*>(payload), uint16_t(strlen(payload)));
}
static void processSpiFrame(const uint8_t *frame);
#if ND_SPI_FORENSIC_DIAGNOSTICS
static const char *spiValidationReason(const uint8_t *frame) {
  if (ND_SPI::get16(frame) != ND_SPI::MAGIC) return "MAGIC";
  if (frame[2] != ND_SPI::VERSION) return "VERSION";
  if (frame[3] > ND_SPI::SPI_MSG_ERROR) return "TYPE";
  if (!ND_SPI::validLength(ND_SPI::get16(frame + 8))) return "LENGTH";
  if (ND_SPI::get32(frame + ND_SPI::HEADER_BYTES + ND_SPI::get16(frame + 8)) != ND_SPI::crc32(frame, ND_SPI::HEADER_BYTES + ND_SPI::get16(frame + 8))) return "CRC";
  return nullptr;
}
#endif
#if ND_SPI_FORENSIC_DIAGNOSTICS
static void captureFirstInvalidSpiFrame(const uint8_t *tx, const uint8_t *rx) {
  if (spiFirstInvalidCaptured) return;
  const char *reason = spiValidationReason(rx);
  if (!reason) return;
  spiFirstInvalidCaptured = true;
  memcpy(spiFirstInvalidTx, tx, sizeof(spiFirstInvalidTx));
  memcpy(spiFirstInvalidRx, rx, sizeof(spiFirstInvalidRx));
  spiFirstInvalidTxSeq = ND_SPI::get32(tx + 4);
  spiFirstInvalidMagic = ND_SPI::get16(rx);
  spiFirstInvalidVersion = rx[2];
  spiFirstInvalidType = rx[3];
  spiFirstInvalidLength = ND_SPI::get16(rx + 8);
  spiFirstInvalidReady = digitalRead(ESP_SPI_READY) ? 1 : 0;
  strncpy(spiFirstInvalidReason, reason, sizeof(spiFirstInvalidReason) - 1);
  Serial.println(F("[SPI FIRST INVALID]"));
  Serial.print(F("txSeq=")); Serial.print(spiFirstInvalidTxSeq);
  Serial.print(F(" reason=")); Serial.println(spiFirstInvalidReason);
  Serial.print(F("TX16=")); for (size_t i = 0; i < sizeof(spiFirstInvalidTx); ++i) { if (i) Serial.print(' '); if (spiFirstInvalidTx[i] < 16) Serial.print('0'); Serial.print(spiFirstInvalidTx[i], HEX); } Serial.println();
  Serial.print(F("RX32=")); for (size_t i = 0; i < sizeof(spiFirstInvalidRx); ++i) { if (i) Serial.print(' '); if (spiFirstInvalidRx[i] < 16) Serial.print('0'); Serial.print(spiFirstInvalidRx[i], HEX); } Serial.println();
  Serial.print(F("magicObserved=0x")); Serial.println(spiFirstInvalidMagic, HEX);
  Serial.print(F("versionObserved=")); Serial.println(spiFirstInvalidVersion);
  Serial.print(F("typeObserved=")); Serial.println(spiFirstInvalidType);
  Serial.print(F("lengthObserved=")); Serial.println(spiFirstInvalidLength);
  Serial.print(F("ready=")); Serial.println(spiFirstInvalidReady);
}
#endif
static void serviceEspSpi() {
  const uint32_t now = millis(); if (spiSynced && now - espUartLastSeenMs > 1500u) { spiSynced = false; ++spiLinkResyncs; } if (now - spiLastPollMs < ESP_SPI_POLL_MS) return; spiLastPollMs = now;
  if (!spiSynced && now - lastEspUartHeartbeatMs >= 500u) { queueSpiHello(); lastEspUartHeartbeatMs = now; }
  if (!spiPop(spiTxFrame)) ND_SPI::build(spiTxFrame, ND_SPI::SPI_MSG_NOP, spiSequence, 0, 0, nullptr, 0);
  SPI1.beginTransaction(SPISettings(ND_SPI::CLOCK_HZ, MSBFIRST, SPI_MODE0)); digitalWrite(ESP_SPI_CS, LOW); SPI1.transfer(spiTxFrame, spiRxFrame, ND_SPI::FRAME_BYTES); digitalWrite(ESP_SPI_CS, HIGH); SPI1.endTransaction();
  ++spiTransactions; espUartTxBytes += ND_SPI::FRAME_BYTES; espUartRxBytes += ND_SPI::FRAME_BYTES;
#if ND_SPI_FORENSIC_DIAGNOSTICS
  captureFirstInvalidSpiFrame(spiTxFrame, spiRxFrame);
#endif
  processSpiFrame(spiRxFrame);
  if (now - spiLastStatusMs >= 5000u) { spiLastStatusMs = now; Serial.print(F("[SPI] synced=")); Serial.print(spiSynced ? 1 : 0); Serial.print(F(" tx=")); Serial.print(spiTransactions); Serial.print(F(" rx=")); Serial.print(spiTransactions); Serial.print(F(" valid=")); Serial.print(spiValidFrames); Serial.print(F(" crc=")); Serial.print(spiCrcErrors); Serial.print(F(" drops=")); Serial.print(spiRxDrops + spiTxDrops + spiLightingDrops); Serial.print(F(" resync=")); Serial.println(spiLinkResyncs); }
}
void initEspUart() { pinMode(ESP_SPI_CS, OUTPUT); digitalWrite(ESP_SPI_CS, HIGH); pinMode(ESP_SPI_READY, INPUT_PULLDOWN); SPI1.setRX(ESP_SPI_MISO); SPI1.setCS(ESP_SPI_CS); SPI1.setSCK(ESP_SPI_SCK); SPI1.setTX(ESP_SPI_MOSI); SPI1.begin(false); espUartReady = true; queueSpiHello(); queueSpiStatusSubscription(); Serial.println(F("[DIAG] ESP32 SPI: PASS (SPI1 GP12/13/14/15 READY GP11 / 1MHz mode 0)")); }
void serviceEspUart() { if (espUartReady) serviceEspSpi(); }

#endif

// W5500-EVB-Pico2 integrated Ethernet allocation.  These GPIOs are routed
// on the board and must not be reassigned to application peripherals.
#define W5500_MISO_PIN 16
#define W5500_CS_PIN   17
#define W5500_SCK_PIN  18
#define W5500_MOSI_PIN 19
#define W5500_RST_PIN  20
#define W5500_INT_PIN  21  // Reserved by the board; Ethernet is polled here.

// Manage the PIO program loading offset
static int pio0_offset = -1;
static int pio1_offset = -1;

// Core cross-conflict flags
volatile bool systemReady = false;
volatile uint32_t core1_heartbeat = 0; 
volatile uint32_t core1Stage = 0;
volatile int8_t core1StagePort = -1;
volatile uint32_t core1LastProgressMs = 0;
spin_lock_t* dmx_lock = nullptr;
// Short, non-blocking ownership flag for the shared DMX buffers.  Neither
// core is allowed to wait forever for the other core.
volatile uint32_t dmx_buffer_busy = 0;

static inline bool tryAcquireDmxBuffer() {
  uint32_t expected = 0;
  return __atomic_compare_exchange_n(&dmx_buffer_busy, &expected, 1u, false,
                                     __ATOMIC_ACQUIRE, __ATOMIC_RELAXED);
}

static inline void releaseDmxBuffer() {
  __atomic_store_n(&dmx_buffer_busy, 0u, __ATOMIC_RELEASE);
}

static inline void setCore1Checkpoint(uint32_t stage, int port = -1) {
  core1StagePort = static_cast<int8_t>(port);
  __atomic_store_n(&core1Stage, stage, __ATOMIC_RELAXED);
}

// ================= PIO DMX DRIVER =================
static const uint16_t dmx_program_instructions[] = {
    0x98a0, // pull block side 1
    0xf327, // set x, 7 side 0 [3]
    0x6201, // out pins, 1 [2]
    0x0042, // jmp x--, 2
    0xbe42  // nop side 1 [6]
};
static const struct pio_program dmx_program = { dmx_program_instructions, 5, -1 };

class PIODMX {
private:
    PIO pio; uint sm; uint offset; uint pin; pio_sm_config c;
public:
    bool begin(PIO pio_hw, uint sm_num, uint tx_pin) {
        pio = pio_hw; sm = sm_num; pin = tx_pin;
        
        if (pio == pio0) {
            if (pio0_offset == -1) pio0_offset = pio_add_program(pio, &dmx_program);
            offset = pio0_offset;
        } else {
            if (pio1_offset == -1) pio1_offset = pio_add_program(pio, &dmx_program);
            offset = pio1_offset;
        }

        c = pio_get_default_sm_config();
        sm_config_set_wrap(&c, offset + 0, offset + 4);
        sm_config_set_out_pins(&c, pin, 1);
        sm_config_set_sideset_pins(&c, pin);
        sm_config_set_sideset(&c, 2, true, false); 
        sm_config_set_out_shift(&c, true, false, 32);
        sm_config_set_fifo_join(&c, PIO_FIFO_JOIN_TX);
        sm_config_set_clkdiv(&c, (float)clock_get_hz(clk_sys) / (250000.0f * 4.0f));

        pio_sm_set_pins_with_mask(pio, sm, 1u << pin, 1u << pin);
        pio_sm_set_pindirs_with_mask(pio, sm, 1u << pin, 1u << pin);
        pio_gpio_init(pio, pin);

        pio_sm_init(pio, sm, offset, &c);
        pio_sm_set_enabled(pio, sm, true);
        return true;
    }
    
    inline bool put_byte(uint8_t b) {
        if (pio_sm_is_tx_fifo_full(pio, sm)) return false;
        pio_sm_put(pio, sm, b);
        return true;
    }

    uint getOffset() const { return offset; }

    // Hold the state machine during BREAK.  The PIO program itself remains
    // configured and is not restarted for every DMX frame.
    void stop() {
        pio_sm_set_enabled(pio, sm, false);
        gpio_set_function(pin, GPIO_FUNC_SIO);
        gpio_set_dir(pin, GPIO_OUT);
    }
    void resume() {
        pio_gpio_init(pio, pin);
        pio_sm_set_pindirs_with_mask(pio, sm, 1u << pin, 1u << pin);
        pio_sm_set_enabled(pio, sm, true);
    }
    
    void reset_sm() {
        pio_sm_set_enabled(pio, sm, false);
        pio_sm_restart(pio, sm);
        pio_sm_clear_fifos(pio, sm);
        pio_sm_exec(pio, sm, pio_encode_jmp(offset));
        pio_sm_clkdiv_restart(pio, 1u << sm);
        pio_gpio_init(pio, pin);
        pio_sm_set_consecutive_pindirs(pio, sm, pin, 1, true);
        pio_sm_set_enabled(pio, sm, true);
    }
};

