static uint8_t ethernetResponseBuffer[16384];
static uint8_t interprocessorResponseBuffer[ESP_UART_RESPONSE_MAX];
static bool interprocessorResponseBusy = false;

class EthernetDashboardWriter : public DashboardWriter {
  EthernetClient& client;
  uint8_t* buffer;
  const size_t capacity;
  size_t length = 0;
  bool overflowed = false;
public:
  explicit EthernetDashboardWriter(EthernetClient& c, uint8_t* responseBuffer)
      : client(c), buffer(responseBuffer), capacity(16384u) {}
  bool connected() const override { return client.connected() && !overflowed; }
  size_t write(uint8_t b) override { return write(&b, 1); }
  size_t write(const uint8_t* data, size_t len) override {
    if (len > capacity - length) { overflowed = true; return 0; }
    memcpy(buffer + length, data, len);
    length += len;
    return len;
  }
  bool flushResponse() {
    size_t sent = 0;
    uint32_t lastProgressMs = millis();
    while (sent < length && client.connected()) {
      const size_t remaining = length - sent;
      const size_t block = remaining > 512 ? 512 : remaining;
      const size_t written = client.write(buffer + sent, block);
      if (written > 0) {
        sent += written;
        lastProgressMs = millis();
        handleNetworkPackets();
        watchdog_update();
      } else {
        if (millis() - lastProgressMs >= 1500u) break;
        handleNetworkPackets();
        watchdog_update();
        delay(1);
      }
    }
    return !overflowed && sent == length;
  }
  void service() override { handleNetworkPackets(); watchdog_update(); }
};

class UartDashboardWriter : public DashboardWriter {
  uint8_t* buffer; const size_t capacity; size_t length = 0; bool overflowed = false;
public:
  explicit UartDashboardWriter(uint8_t* responseBuffer) : buffer(responseBuffer), capacity(ESP_UART_RESPONSE_MAX) {}
  bool connected() const override { return !overflowed; }
  size_t write(uint8_t b) override { return write(&b, 1); }
  size_t write(const uint8_t* data, size_t len) override {
    if (len > capacity - length) { overflowed = true; return 0; }
    memcpy(buffer + length, data, len); length += len; return len;
  }
  const uint8_t* data() const { return buffer; }
  size_t size() const { return length; }
};

#if ND_INTERPROCESS_SPI
static bool spiQueueFrame(uint8_t type, uint32_t sequence, uint16_t flags, uint32_t channel, const uint8_t *payload, uint16_t length, bool lighting);
void dispatchDashboardRequest(DashboardWriter& client, const char* requestLine);
static void queueSpiApiResponse(uint16_t requestId, const UartDashboardWriter& response) {
  ++espHttpResponsesStarted; lastResponseId = requestId; lastResponseBytes = response.size();
  const size_t chunk = ND_SPI::MAX_PAYLOAD;
  if (!response.size()) { const uint8_t empty = 0; spiQueueFrame(ND_SPI::SPI_MSG_API_RESPONSE, spiSequence, ND_SPI::FLAG_FIRST | ND_SPI::FLAG_LAST, requestId, &empty, 0); }
  for (size_t off = 0; off < response.size(); off += chunk) {
    const size_t n = (response.size() - off > chunk) ? chunk : response.size() - off;
    uint16_t flags = (off == 0 ? ND_SPI::FLAG_FIRST : 0) | (off + n < response.size() ? ND_SPI::FLAG_MORE : ND_SPI::FLAG_LAST);
    if (!spiQueueFrame(ND_SPI::SPI_MSG_API_RESPONSE, spiSequence, flags, requestId, response.data() + off, uint16_t(n))) break;
    ++espHttpDataChunksSent;
  }
  ++espHttpResponsesCompleted;
}

static void processSpiFrame(const uint8_t *frame) {
  ++espUartRxLines;
  uint8_t error = 0;
  if (!ND_SPI::validate(frame, &error)) { ++espUartInvalidFrames; if (error == 1) ++spiMagicErrors; else if (error == 2) ++spiVersionErrors; else if (error == 3) ++spiLengthErrors; else ++spiCrcErrors; ++spiRxDrops; return; }
  ++spiValidFrames; ++espUartValidFrames; ++espValidFrameCount; espUartLinkAlive = true; espUartLastSeenMs = millis();
  const uint8_t type = frame[3]; const uint16_t length = ND_SPI::get16(frame + 8); const uint32_t channel = ND_SPI::get32(frame + 12); const uint8_t *payload = frame + ND_SPI::HEADER_BYTES;
  if (type == ND_SPI::SPI_MSG_HELLO || type == ND_SPI::SPI_MSG_HELLO_ACK) {
    spiSynced = true; ++espUartReadyFrames; strncpy(espLastFrameType, "HELLO", sizeof(espLastFrameType) - 1); return;
  }
  if (type == ND_SPI::SPI_MSG_STATUS_REQUEST) return;
  if (type == ND_SPI::SPI_MSG_API_REQUEST) {
    if (length == 0 || length >= ESP_UART_REQUEST_MAX) { ++spiRxDrops; return; }
    if (interprocessorResponseBusy) { ++spiRxDrops; return; }
    interprocessorResponseBusy = true;
    ++espUartReqFrames; ++espHttpReqReceived; lastReqId = uint16_t(channel); UartDashboardWriter response(interprocessorResponseBuffer); char request[ESP_UART_REQUEST_MAX]; memcpy(request, payload, length); request[length] = '\0'; dispatchDashboardRequest(response, request); queueSpiApiResponse(uint16_t(channel), response); interprocessorResponseBusy = false; return;
  }
  if (type == ND_SPI::SPI_MSG_ARTNET_UNIVERSE || type == ND_SPI::SPI_MSG_SACN_UNIVERSE) {
    if (length < 5 || length - 5 > 512) { ++spiRxDrops; ++spiLightingDrops; return; }
    const uint16_t universe = uint16_t(channel); const uint8_t priority = payload[0]; IPAddress source(payload[1], payload[2], payload[3], payload[4]);
    const char *name = type == ND_SPI::SPI_MSG_ARTNET_UNIVERSE ? "Art-Net" : "sACN";
    for (int i = 0; i < 4; ++i) if (ports[i].universe == universe && cfg.portEnabled[i]) { processDmxData(i, const_cast<uint8_t*>(payload + 5), uint16_t(length - 5), priority, source, name); if (type == ND_SPI::SPI_MSG_ARTNET_UNIVERSE) ++espWifiArtRxCount; else ++espWifiSacnRxCount; return; }
    ++spiRxDrops; ++spiLightingDrops; return;
  }
  if (type == ND_SPI::SPI_MSG_STATUS_RESPONSE) {
    if (length >= 5 && !memcmp(payload, "ACK|", 4)) { unsigned long id = strtoul(reinterpret_cast<const char*>(payload + 4), nullptr, 10); if (espWifiConfigPending && uint16_t(id) == espWifiConfigPendingId) { espWifiConfigAcked = true; espWifiConfigPending = false; strncpy(espWifiConfigAckMessage, "wifi-applied", sizeof(espWifiConfigAckMessage) - 1); } return; }
    const size_t n = length < sizeof(espWifiStatus) - 1 ? length : sizeof(espWifiStatus) - 1; memcpy(espWifiStatus, payload, n); espWifiStatus[n] = '\0'; ++espTelemetryFrameCount; ++espTelemetryDecodeSuccessCount; strncpy(espLastFrameType, "STATUS", sizeof(espLastFrameType) - 1); return;
  }
}
#endif

bool writeAll(DashboardWriter& client, const uint8_t* data, size_t length) {
  const size_t CHUNK_SIZE = 512;
  size_t sent = 0;
  uint32_t lastProgressMs = millis();

  while (sent < length && client.connected()) {
    const size_t remaining = length - sent;
    const size_t block = remaining > CHUNK_SIZE ? CHUNK_SIZE : remaining;
    const size_t written = client.write(data + sent, block);

    if (written > 0) {
      sent += written;
      lastProgressMs = millis();
      client.service();
    } else {
      if (millis() - lastProgressMs > 1500) break;
      delay(1);
    }
  }
  return sent == length;
}

bool writeAll(DashboardWriter& client, const char* data, size_t length) {
  return writeAll(client, reinterpret_cast<const uint8_t*>(data), length);
}

void sendStaticHeader(DashboardWriter& client, const char* status, const char* contentType, size_t contentLength, const char* cacheControl) {
  char header[320];
  const int count = snprintf(
    header, sizeof(header),
    "HTTP/1.1 %s\r\nContent-Type: %s\r\nContent-Length: %lu\r\nCache-Control: %s\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n",
    status, contentType, static_cast<unsigned long>(contentLength), cacheControl
  );
  if (count > 0) writeAll(client, header, static_cast<size_t>(count));
}

void sendDynamicJsonHeader(DashboardWriter& client, bool ok = true) {
  client.println(ok ? F("HTTP/1.1 200 OK") : F("HTTP/1.1 400 Bad Request"));
  client.println(F("Content-Type: application/json; charset=utf-8"));
  client.println(F("Cache-Control: no-store, no-cache, must-revalidate"));
  client.println(F("X-Content-Type-Options: nosniff"));
  client.println(F("Connection: close"));
  client.println();
}

void printJsonString(DashboardWriter& client, const char* value) {
  client.print('"');
  if (value) {
    for (const char* p = value; *p; ++p) {
      const char ch = *p;
      if (ch == '"' || ch == '\\') { client.print('\\'); client.print(ch); } 
      else if (ch == '\n') { client.print(F("\\n")); } 
      else if (static_cast<uint8_t>(ch) >= 0x20) { client.print(ch); }
    }
  }
  client.print('"');
}

void printMacString(DashboardWriter& client) {
  client.print('"');
  for (int i = 0; i < 6; ++i) {
    if (i) client.print(':');
    if (mac[i] < 16) client.print('0');
    client.print(mac[i], HEX);
  }
  client.print('"');
}

uint64_t getSystemUptimeSeconds() { return time_us_64() / 1000000ULL; }

static const char* rpSpiHealthName(uint32_t now) {
  if (!espUartReady) return "FAILED";
  if (!spiSynced || espUartLastSeenMs == 0 || now - espUartLastSeenMs > RP_SPI_HEALTH_TIMEOUT_MS) return "DEGRADED";
  return "HEALTHY";
}

static uint32_t rpSpiLastValidAge(uint32_t now) {
  return espUartLastSeenMs == 0 ? 0xFFFFFFFFu : now - espUartLastSeenMs;
}

void printUInt64(DashboardWriter& client, uint64_t value) {
  char buffer[24]; snprintf(buffer, sizeof(buffer), "%llu", static_cast<unsigned long long>(value)); client.print(buffer);
}

